import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_span, rounded_labels, snap_minutes


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 45, 120):
            with self.assertRaises(ValueError):
                rounded_labels([Span(60, 120)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 15, 30, 60):
            self.assertEqual(len(rounded_labels([Span(60, 300)], step)), 1)


class SnapTests(unittest.TestCase):
    def test_nearest(self):
        self.assertEqual(snap_minutes(7, 15), 0)
        self.assertEqual(snap_minutes(8, 15), 15)
        self.assertEqual(snap_minutes(22, 15), 15)

    def test_exact_half_goes_up(self):
        self.assertEqual(snap_minutes(30, 60), 60)

    def test_round_span(self):
        self.assertEqual(round_span(parse_span("08:58-17:12"), 15), parse_span("09:00-17:15"))

    def test_span_collapsing_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 64), 15)

    def test_rounding_up_to_midnight(self):
        self.assertEqual(round_span(Span(1400, 1439), 15), Span(1395, 1440))


class LabelTests(unittest.TestCase):
    def test_label(self):
        spans = [parse_span("09:02-17:14")]
        self.assertEqual(rounded_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_order_kept_and_short_durations(self):
        spans = [parse_span("13:00-13:50"), parse_span("08:00-09:00")]
        self.assertEqual(
            rounded_labels(spans, 30),
            ["13:00-14:00 (1h 0m)", "08:00-09:00 (1h 0m)"]
        )

    def test_under_an_hour(self):
        self.assertEqual(rounded_labels([parse_span("10:00-10:45")], 15), ["10:00-10:45 (0h 45m)"])
